  function recordPortalLogin(role,user){const d=db()||{},key=role==='student'?'students':role==='teacher'?'teachers':'admins',record=(d[key]||[]).find(x=>x.id===user.id);if(!record)return;const entry={at:new Date().toISOString(),device:navigator.userAgentData?.platform||navigator.platform||'Browser'};record.loginTrail=Array.isArray(record.loginTrail)?record.loginTrail:[];record.loginTrail.unshift(entry);record.loginTrail=record.loginTrail.slice(0,3);user.loginTrail=record.loginTrail;saveDB(d)}
  function loginTrailCard(role,user){const trail=Array.isArray(user?.loginTrail)?user.loginTrail.slice(0,3):[];return `<section class="card portal-login-trail"><div class="login-trail-head"><div><span class="kicker">Account activity</span><h2>Last 3 logins</h2></div><span class="pill">${trail.length} of 3</span></div>${trail.map((x,i)=>`<div class="login-trail-row"><span class="login-trail-index">0${i+1}</span><span><b>${i===0?'Most recent sign-in':'Previous sign-in'}</b><small>${new Date(x.at).toLocaleString('en-IN')} · ${escapeHtml(x.device||'Browser')}</small></span></div>`).join('')||'<p class="muted">Your successful sign-ins will appear here.</p>'}</section>`}
  function portalNoticeBoard(role){const rows=(noticesData()||[]).map(n=>Array.isArray(n)?{date:n[0],title:n[1],description:n[2]}:{date:n.date||n.createdAt||'',title:n.title||n.name||'College notice',description:n.description||n.body||n.text||''});return `<section class="card portal-notice-board"><div class="hierarchy-head"><div><span class="kicker">${role==='teacher'?'Faculty':'Student'} services</span><h2>College notices</h2><p class="muted">Announcements published by the college administration.</p></div><span class="pill">${rows.length} notices</span></div><div class="notice-list">${rows.map(n=>`<article class="portal-notice-row"><div><span class="kicker">${escapeHtml(n.date)}</span><h3>${escapeHtml(n.title)}</h3><p>${escapeHtml(n.description)}</p></div></article>`).join('')||'<div class="empty">There are no published notices right now.</div>'}</div></section>`}

  window.portalLogin=function(e){
    e.preventDefault();
    const rawUser=document.getElementById('loginUser')?.value||'';
    const user=rawUser.trim().replace(/\s+/g,' ').toLowerCase();
    const password=document.getElementById('loginPass')?.value.trim()||'';
    const matches=v=>String(v||'').trim().replace(/\s+/g,' ').toLowerCase()===user;
    let who=null;
    if(role==='student') who=students().find(x=>(matches(x.username)||matches(x.id)||matches(x.studentId)||matches(x.name))&&String(x.password??'').trim()===password);
    if(role==='teacher') who=teachers().find(x=>(matches(x.username)||matches(x.id))&&String(x.password??'').trim()===password);
    if(role==='admin') who=admins().find(x=>(matches(x.username)||matches(x.id))&&String(x.password??'').trim()===password);
    if(!who){showLoginError('We couldn’t find a matching account. Check your username and password, then try again.');return;}
    if(who.status==='Inactive'){showLoginError('This account is inactive. Please contact the college administrator.');return;}
    clearLoginError();recordPortalLogin(role,who);setSession({...who,role});location.hash=`/portal/${role}`;closeLogin();
  };

