  function finalAdminDayStatus(status){const daily=adminDailyContext();if(!['Working Day','Holiday'].includes(status))return;daily.record.status=status;daily.list.forEach(x=>{daily.record.records[x.id]=status==='Holiday'?'H':(daily.record.records[x.id]==='H'?'':'');daily.data.attendanceLogs=daily.data.attendanceLogs||{};daily.data.attendanceLogs[x.id]=daily.data.attendanceLogs[x.id]||{};if(status==='Holiday')daily.data.attendanceLogs[x.id][daily.date]='H';else if(daily.data.attendanceLogs[x.id][daily.date]==='H')delete daily.data.attendanceLogs[x.id][daily.date];});saveDB(daily.data);route();}
