  /* ------------------------------------------------------------------
     FINAL ROUTER HANDOFF
     The base app.js installs hash listeners before this upgrade file is
     loaded.  The upgraded portal router is local to this IIFE, so without
     handing it back to the global navigation lifecycle, portal pages only
     become correct after a full HTML refresh.
     ------------------------------------------------------------------ */
  window.__shakuntalamPortalRoute = route;
  window.examination = examinationFinal;
  window.home = window.home || window.home;
  const _baseShakuntalamRoute = window.route;
  function finalRoute(){
    const path=location.hash.replace(/^#/,'')||'/';
    const previousPath=window._lastFinalRoutePath; const previousScroll=window.scrollY||0; const samePath=previousPath===path;
    /* Keep deep portal navigation on the upgraded router. The base app router
       only understands the top-level portal section and replaces the grouped
       sidebar with its legacy flat version on semester/detail hashes. */
    if(path.startsWith('/portal/')){window.__shakuntalamPortalRoute();return;}
    if(path.startsWith('/examination/') && path!=='/examination') {
      const kind=path.split('/').filter(Boolean)[1]||'calendar';
      app.innerHTML=examinationSubPage(kind)+loginModal();
      startClock(); window._lastFinalRoutePath=path; requestAnimationFrame(()=>window.scrollTo(0,samePath?previousScroll:0)); return;
    }
    _baseShakuntalamRoute();
    if(path==='/'){
      const sections=[...document.querySelectorAll('section.section')];
      sections.find(sec=>/Notice board/i.test(sec.querySelector('h2')?.textContent||''))?.remove();
    }
    window._lastFinalRoutePath=path; requestAnimationFrame(()=>window.scrollTo(0,samePath?previousScroll:0));
  }
  window.route = finalRoute;
  // app.js registered its base route before this upgrade loaded. Remove that
  // exact base listener so a later hashchange cannot replace the grouped
  // portal sidebar with the legacy flat sidebar after refresh or navigation.
  window.removeEventListener('hashchange', _baseShakuntalamRoute);
  window.removeEventListener('load', _baseShakuntalamRoute);
  window.removeEventListener('hashchange', originalRoute);
  window.removeEventListener('load', originalRoute);
  window.addEventListener('hashchange', finalRoute);
  window.addEventListener('load', finalRoute);

  /* Ensure a portal link clicked immediately after login renders the new
     screen even if the browser batches the hashchange event. */
  document.addEventListener('click', function(ev){
    const link = ev.target && ev.target.closest ? ev.target.closest('a[href^="#/portal/"]') : null;
    if(!link) return;
    requestAnimationFrame(function(){
      try { route(); } catch(err) { console.error('Portal route error:', err); }
    });
  });
  document.addEventListener('scroll',function(ev){
    if(ev.target&&ev.target.matches&&ev.target.matches('.blink-side .side-scroll')) window._portalSidebarScrollTop=ev.target.scrollTop;
  },true);
  document.addEventListener('click',function(ev){
    const link=ev.target&&ev.target.closest?ev.target.closest('.blink-side .side-scroll a[href^="#/portal/"]'):null;
    if(link){const side=link.closest('.blink-side')?.querySelector('.side-scroll');if(side)window._portalSidebarClickScroll=side.scrollTop;}
  },true);

  /* Manual hero carousel controls — four-to-three portrait-safe frame. */
  window.animatePublicCarousel=async function(frame,image,src,alt,direction=1,onDone){
    if(!frame||!image||!src||frame.dataset.carouselAnimating==='true')return;
    frame.dataset.carouselAnimating='true';
    let incoming=null;
    try{
      /* Decode before starting so the outgoing image remains visible until
         the next image is fully ready, even on a slow mobile connection. */
      incoming=new Image();incoming.alt=alt||'';incoming.draggable=false;incoming.decoding='async';incoming.src=src;
      if(incoming.decode)await incoming.decode();
      else await new Promise((resolve,reject)=>{incoming.onload=resolve;incoming.onerror=reject});
      const frameBox=frame.getBoundingClientRect(),imageBox=image.getBoundingClientRect();
      incoming.className='carousel-slide-overlay';
      incoming.style.top=`${imageBox.top-frameBox.top}px`;incoming.style.left=`${imageBox.left-frameBox.left}px`;
      incoming.style.width=`${imageBox.width}px`;incoming.style.height=`${imageBox.height}px`;
      const computed=getComputedStyle(image);incoming.style.objectFit=computed.objectFit;incoming.style.objectPosition=computed.objectPosition;incoming.style.borderRadius=computed.borderRadius;
      incoming.style.transform=`translateX(${direction*105}%)`;frame.appendChild(incoming);
      await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
      image.classList.add('carousel-slide-out');image.style.transform=`translateX(${-direction*105}%)`;incoming.style.transform='translateX(0)';
      await new Promise(resolve=>setTimeout(resolve,560));
      /* Promote the already decoded, visible slide into the original image
         element's place. Avoid changing src on a live image, which can flash
         while the browser fetches or decodes it again. */
      const id=image.id,classes=image.className.split(/\s+/).filter(name=>name&&name!=='carousel-slide-out').join(' ');
      incoming.id=id;incoming.className=classes;
      ['top','left','width','height','transform','objectFit','objectPosition','borderRadius','transition','zIndex','position'].forEach(key=>incoming.style[key]='');
      image.replaceWith(incoming);incoming=null;
      if(onDone)onDone();
    }catch(error){
      if(incoming&&incoming.parentNode)incoming.remove();
    }finally{frame.dataset.carouselAnimating='false'}
  };
  window.nextHeroSlideV7=function(direction){
    const slides=(db()?.site?.heroSlides||[]).filter(x=>x&&x.image),imgEl=document.getElementById('heroCarouselImage')||document.querySelector('.hero-card img');
    if(!imgEl||!slides.length)return;
    const frame=imgEl.closest('.hero-card');if(frame?.dataset.carouselAnimating==='true')return;
    let i=Number.isFinite(window._heroCarouselIndex)?window._heroCarouselIndex:0;
    const current=slides.findIndex(x=>x.image===imgEl.getAttribute('src')||x.image===imgEl.src);
    if(current>=0)i=current;
    i=(i+(direction>0?1:-1)+slides.length)%slides.length;window._heroCarouselIndex=i;
    const title=slides[i].title||'Shakuntalam College';
    window.animatePublicCarousel(frame,imgEl,slides[i].image,title,direction,()=>{const cap=document.querySelector('.hero-card-caption');if(cap){const b=cap.querySelector('b');if(b)b.textContent=title}});
    clearInterval(window._heroCarouselTimer);window._heroCarouselTimer=setInterval(()=>window.nextHeroSlideV7(1),5000);
  };
  let carouselSwipeStart=null;
  document.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse')return;const frame=event.target.closest?.('.hero-card,[data-home-carousel]');if(frame)carouselSwipeStart={frame,x:event.clientX,y:event.clientY}},{passive:true,capture:true});
  document.addEventListener('pointerup',event=>{const start=carouselSwipeStart;carouselSwipeStart=null;if(!start)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(Math.abs(dx)<40||Math.abs(dx)<Math.abs(dy)*1.2)return;if(start.frame.matches('.hero-card'))window.nextHeroSlideV7(dx<0?1:-1);else stepHomeImageCarousel(start.frame.dataset.homeCarousel,dx<0?1:-1)},{passive:true,capture:true});
